const items = $input.all();

return items.map(item => {
  const msg = item.json.message;
  const chatId = msg.chat.id;
  const originalText = msg.text;

  const sanitized = originalText
    .replace(/["\\]/g, '')
    .replace(/[<>{}|]/g, '')
    .trim();

  const text = sanitized.toLowerCase();
  const rejectKeywords = [
    'producto', 'ecommerce', 'tienda', 'manufactura', 'fábrica',
    'fabrica', 'comercio', 'venta de', 'distribuidor'
  ];
  const isObviousReject = rejectKeywords.some(w => text.includes(w));
  const isTooShort = text.length < 10;
  const skipGroq = isObviousReject || isTooShort;

  if (skipGroq) {
    let reason;
    if (isTooShort) {
      reason = 'Mensaje demasiado corto. Envía más información: tipo de empresa, empleados, ubicación e interés.';
    } else {
      reason = 'La empresa no es de tipo servicios o consultoría. Buscamos empresas de servicios, consultoría o transformación digital.';
    }
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    const timestamp = pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());

    return {
      json: {
        chatId,
        originalText,
        replyText: '❌ NO CALIFICADO\n\n' + reason,
        decision: '[NO CALIFICADO]',
        reason: reason,
        timestamp,
        skipGroq: true
      }
    };
  }

  return {
    json: {
      chatId,
      originalText,
      sanitizedText: sanitized,
      skipGroq: false
    }
  };
});

const items = $input.all();

return items.map(item => {
  const r = item.json;
  const chatId = $node['Pre-filter'].json.chatId;
  const originalText = $node['Pre-filter'].json.originalText;

  const d = new Date();
  const pad = n => String(n).padStart(2, '0');
  const timestamp = pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());

  let parsed = null;
  let rawText = '';

  try {
    const choices = r.choices || [];
    if (choices.length > 0 && choices[0].message) {
      rawText = choices[0].message.content || '';
    } else if (choices.length > 0 && choices[0].text) {
      rawText = choices[0].text || '';
    } else {
      rawText = JSON.stringify(r);
    }

    rawText = rawText.trim();
    if (!rawText) { throw new Error('No text in response'); }

    let cleanRaw = rawText;
    if (cleanRaw.startsWith('```json')) cleanRaw = cleanRaw.slice(7);
    else if (cleanRaw.startsWith('```')) cleanRaw = cleanRaw.slice(3);
    if (cleanRaw.endsWith('```')) cleanRaw = cleanRaw.slice(0, -3);
    cleanRaw = cleanRaw.trim();

    const first = cleanRaw.indexOf('{');
    if (first === -1) {
      throw new Error('No JSON found. Raw: ' + rawText.substring(0, 100));
    }

    let openCount = 0;
    let closePos = -1;
    for (let i = first; i < cleanRaw.length; i++) {
      if (cleanRaw[i] === '{') openCount++;
      if (cleanRaw[i] === '}') {
        openCount--;
        if (openCount === 0) {
          closePos = i;
          break;
        }
      }
    }

    if (closePos === -1) {
      throw new Error('Unclosed JSON');
    }

    let candidate = cleanRaw.substring(first, closePos + 1);

    try {
      parsed = JSON.parse(candidate);
    } catch (e1) {
      let cleaned = candidate.replace(/,\s*([\]}])/g, '$1');
      try { parsed = JSON.parse(cleaned); }
      catch (e2) {
        let attempt = cleaned.replace(/([\]}])/g, '');
        if (attempt.includes('"qualified"')) {
          let qMatch = attempt.match(/"qualified"\s*:\s*(true|false)/);
          let rMatch = attempt.match(/"reasoning"\s*:\s*"([^"]*)/);
          if (qMatch) { parsed = { qualified: qMatch[1] === 'true', reasoning: rMatch ? rMatch[1] : 'Sin razonamiento' }; }
        }
        if (!parsed) throw new Error('JSON parsing failed');
      }
    }
  } catch (e) {
    parsed = { qualified: false, reasoning: 'Error al procesar la respuesta. Intenta de nuevo.' };
  }

  const qualified = parsed && parsed.qualified === true;
  const reasoning = (parsed && parsed.reasoning) ? parsed.reasoning : 'Sin razonamiento.';

  let header, headerPlain;
  if (qualified) {
    header = '\u2705 CALIFICADO';
    headerPlain = '[CALIFICADO]';
  } else {
    header = '\u274C NO CALIFICADO';
    headerPlain = '[NO CALIFICADO]';
  }

  const replyText = header + '\n\n' + reasoning;

  return {
    json: {
      chatId,
      replyText,
      decision: headerPlain,
      reason: reasoning,
      originalText,
      timestamp
    }
  };
});
